	@Test
	void multiplicityAggregateFoldsWildcardRunSizes() throws Exception {
		Kernel boundRoot = new Kernel(1,
				List.of(new EnumeratePredicates(0, true, true,
						LmdbWildcardPhysicalDemand.Demand.PAIR_MULTIPLICITY, Operand.constant(0), null, 0, -1,
						-1, null, false)),
				new Aggregate(new int[0], new AggregateOutput[] { AggregateOutput.countStar() }, null,
						OutputMods.none()));
		Kernel allUnbound = new Kernel(3,
				List.of(new EnumerateWildcard(0, true, LmdbWildcardPhysicalDemand.Demand.PAIR_MULTIPLICITY,
						0, 1, 2, -1, null, false)),
				new Aggregate(new int[0], new AggregateOutput[] { AggregateOutput.countStar() }, null,
						OutputMods.none()));

		String boundSource = LmdbNativeKernelEmitter.emit(boundRoot);
		String allSource = LmdbNativeKernelEmitter.emit(allUnbound);
		assertTrue(boundSource.contains("updateBy(end);"), boundSource);
		assertTrue(allSource.contains("updateBy(end);"), allSource);
		assertEquals(false, boundSource.contains(".neighborAt("), boundSource);
		assertEquals(false, allSource.contains(".neighborAt("), allSource);
		assertAggregateDemand(boundRoot, new long[] { 1 }, 3L);
		assertAggregateDemand(allUnbound, new long[0], 4L);
	}

