	@Test
	void wideWildcardLoopsObserveCooperativeCancellation() throws Exception {
		Kernel ir = new Kernel(4,
				List.of(new EnumerateWildcard(0, true, LmdbWildcardPhysicalDemand.Demand.PAYLOAD, 0, 1, 2, 3,
						null, false)),
				emit(0, 1, 2, 3));
		KernelCancellation expired = new KernelCancellation(System.nanoTime() - 1L);

		assertThrows(KernelCancelledException.class,
				() -> runCompiled(ir, new long[0], new FixtureWildcard[] { wideFixture(2_049) }, null, 2_049,
						expired));
		assertThrows(KernelCancelledException.class,
				() -> runInterpreted(ir, new long[0], new FixtureWildcard[] { wideFixture(2_049) }, null, 2_049,
						expired));
	}

	@Test
	void corruptionAfterPartialOutputPropagatesWithoutReplay() throws Exception {
		Kernel ir = new Kernel(4,
				List.of(new EnumerateWildcard(0, true, LmdbWildcardPhysicalDemand.Demand.PAYLOAD, 0, 1, 2, 3,
						null, false)),
				emit(0, 1, 2, 3));

		assertPartialThenCorrupt(compiledKernel(ir), ir, partialCorruptionFixture());
		assertThrows(IllegalStateException.class,
				() -> runInterpreted(ir, partialCorruptionFixture(), 1),
				"the materializing interpreter must propagate before exposing any partial rows");
	}

	private static void assertDemand(Kernel ir, long[][] expected) throws Exception {
		FixtureWildcard compiled = fixture();
		assertRows(runCompiled(ir, new long[0], new FixtureWildcard[] { compiled }, null, 1), expected);
		assertEquals(0, compiled.neighborReads, "compiled demand decoded a neighbor payload");
		assertEquals(0, compiled.contextReads, "compiled unrestricted demand decoded a context payload");
		FixtureWildcard interpreted = fixture();
		assertRows(runInterpreted(ir, new long[0], new FixtureWildcard[] { interpreted }, null, 1), expected);
		assertEquals(0, interpreted.neighborReads, "interpreted demand decoded a neighbor payload");
		assertEquals(0, interpreted.contextReads, "interpreted unrestricted demand decoded a context payload");
	}

