		assertEquals(0, compiled.contextReads, "compiled unrestricted bound-root demand decoded a context payload");
		FixtureWildcard interpreted = fixture();
		assertRows(runInterpreted(ir, constants, new FixtureWildcard[] { interpreted }, null, 1), expected);
		assertEquals(0, interpreted.neighborReads, "interpreted bound-root demand decoded a neighbor payload");
